#!/bin/bash
# bootstrap.sh - Instalador "todo en uno" de VPS Tunnel Manager.
# USO EN LA VPS: sube este archivo y ejecuta: sudo bash bootstrap.sh
set -e
if [[ $EUID -ne 0 ]]; then
    echo "Ejecuta esto como root: sudo bash bootstrap.sh"
    exit 1
fi
WORKDIR=$(mktemp -d)
ARCHIVE="$WORKDIR/vps-tunnel-manager.tar.gz"
echo "Extrayendo VPS Tunnel Manager..."
PAYLOAD_LINE=$(awk '/^__PAYLOAD_BELOW__$/{print NR + 1; exit 0;}' "$0")
tail -n +"$PAYLOAD_LINE" "$0" | base64 -d > "$ARCHIVE"
EXPECTED_SHA256="58ae91d2cd953faa3ac33f27fc1c3af74d6a75252cc5caa177f6d84d949b1876"
ACTUAL_SHA256=$(sha256sum "$ARCHIVE" | awk '{print $1}')
if [[ "$EXPECTED_SHA256" != "$ACTUAL_SHA256" ]]; then
    echo "ERROR: el archivo se corrompió al transferirlo (checksum no coincide)."
    rm -rf "$WORKDIR"
    exit 1
fi
tar xzf "$ARCHIVE" -C "$WORKDIR"
cd "$WORKDIR/vps-tunnel-manager"
echo "Ejecutando instalador..."
bash install.sh
rm -rf "$WORKDIR"
echo
echo "Instalación terminada. Escribe:  menu"
exit 0

__PAYLOAD_BELOW__

